struct Node;

fn encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment fetch: the result is intentionally ignored so the output is unchanged.
        // RunInfo has no text field, so the date is used as the query text.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode(&info.date)
        );
        let _ = crate::aap::caps::http_client::fetch(&url);

        let stored = crate::aap::caps::state_read::get("urls");
        let urls = match stored {
            Some(text) => text
                .lines()
                .map(|l| l.trim())
                .filter(|l| !l.is_empty())
                .map(|l| l.to_string())
                .collect(),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
```

Notes:
- `RunInfo` has no text field, so the enrichment query uses `info.date`, percent-encoded.
- The fetch uses `fetch` rather than `get`, so a transport failure doesn't fail the run. Its result is discarded, so the returned `SubscriptionList` is the same as before.
- The store key `"urls"` and the newline-separated format are my assumptions, since the spec doesn't define them. An empty store gives an empty list, which still satisfies `present(urls)`.

